/**
 * Login use case.
 *
 * <p>Looks the user up by username and compares the supplied password against the stored
 * BCrypt hash via the {@link PasswordEncoder}. On success it returns a
 * {@code code 200 / "登录成功"} envelope whose data carries a freshly generated JWT plus the
 * username and role; otherwise a {@code code 401 / "用户名或密码错误"} envelope.</p>
 */
@Service
public class AuthService {

    private final UserMapper userMapper;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtil jwtUtil;

