package com.cloudrecord.platform.config;

import com.cloudrecord.platform.entity.FilingOrder;
import com.cloudrecord.platform.entity.User;
import com.cloudrecord.platform.mapper.FilingOrderMapper;
import com.cloudrecord.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

/**
 * Idempotent startup seeding, run on every startup after Spring's SQL initialization has
 * created the schema (a {@link CommandLineRunner} executes once the context is ready).
 *
 * <p>Inserts the initial users (each only when that username is absent) and the two
 * initial filing orders (each only when its owner does not already have an order with that
 * order number), so repeated startups never duplicate a seed row.</p>
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final FilingOrderMapper filingOrderMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           FilingOrderMapper filingOrderMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.filingOrderMapper = filingOrderMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        seedUser("admin", "admin123", "ADMIN");
        seedUser("alice", "alice123", "USER");
        seedUser("bob", "bob123", "USER");

        User admin = userMapper.findByUsername("admin");
        User alice = userMapper.findByUsername("alice");

        if (admin != null) {
            seedOrder(admin.getId(), "BA20240601001", "APPROVED",
                    "admin-site.com", "管理科技有限公司",
                    LocalDateTime.of(2024, 6, 1, 10, 0, 0));
        }
        if (alice != null) {
            seedOrder(alice.getId(), "BA20240601002", "REVIEWING",
                    "alice-blog.cn", "爱丽丝网络工作室",
                    LocalDateTime.of(2024, 6, 1, 11, 0, 0));
        }
    }

    private void seedUser(String username, String rawPassword, String role) {
        if (userMapper.countByUsername(username) > 0) {
            return;
        }
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());
        userMapper.insert(user);
    }

    private void seedOrder(Long userId, String orderNo, String status,
                           String domainName, String companyName, LocalDateTime createdAt) {
        boolean alreadyPresent = filingOrderMapper.findByUserId(userId).stream()
                .anyMatch(order -> orderNo.equals(order.getOrderNo()));
        if (alreadyPresent) {
            return;
        }
        FilingOrder order = new FilingOrder();
        order.setUserId(userId);
        order.setOrderNo(orderNo);
        order.setStatus(status);
        order.setDomainName(domainName);
        order.setCompanyName(companyName);
        order.setCreatedAt(createdAt);
        filingOrderMapper.insert(order);
    }
}

package com.cloudrecord.platform.config;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;

/**
 * Issues and verifies the HMAC-signed JSON Web Tokens used for Bearer authentication.
 *
 * <p>Consumes the retained properties {@code jwt.secret} (signing key material) and
 * {@code jwt.expiration} (token *** in milliseconds). Tokens carry the user's id,
 * username, and role. This is the only class that touches the JJWT API directly; the
 * request filter and controllers work through {@link JwtPrincipal} so they remain
 * independent of the token ***
 */
@Component
public class JwtUtil {

    private final SecretKey signingKey;
    private final long expirationMillis;

    public JwtUtil(@Value("${jwt.secret}") String secret,
                   @Value("${jwt.expiration}") long expirationMillis) {
        this.signingKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.expirationMillis = expirationMillis;
    }

    /**
     * Builds a signed token for the given identity, issued now and expiring
     * {@code jwt.expiration} milliseconds later.
     */
    public String generateToken(Long userId, String username, String role) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expirationMillis);
        return Jwts.builder()
                .setSubject(username)
                .claim("userId", userId)
                .claim("role", role)
                .setIssuedAt(now)
                .setExpiration(expiry)
                .signWith(signingKey)
                .compact();
    }

    /**
     * Verifies the token's signature and expiry against {@code jwt.secret}.
     *
     * @return the calling identity, or {@code null} if the token is missing, malformed,
     *         carries a bad signature, or is expired.
     */
    public JwtPrincipal validateToken(String token) {
        if (token == null || token.isBlank()) {
            return null;
        }
        try {
            Claims claims = Jwts.parserBuilder()
                    .setSigningKey(signingKey)
                    .build()
                    .parseClaimsJws(token)
                    .getBody();
            Long userId = toLong(claims.get("userId"));
            String username = claims.getSubject();
            String role = claims.get("role") == null ? null : claims.get("role").toString();
            return new JwtPrincipal(userId, username, role);
        } catch (Exception ex) {
            // Signature mismatch, expiry, malformed token, etc. -> treat as unauthenticated.
            return null;
        }
    }

    private static Long toLong(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Number number) {
            return number.longValue();
        }
        try {
            return Long.valueOf(value.toString());
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    /**
     * The authenticated calling identity established from a verified token.
     */
    public record JwtPrincipal(Long userId, String username, String role) {
    }
}

package com.cloudrecord.platform.config;

import com.cloudrecord.platform.dto.ApiResponse;
import com.cloudrecord.platform.filter.JwtAuthFilter;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

import java.io.IOException;

/**
 * Spring Security wiring for the platform.
 *
 * <p>Exposes the BCrypt {@link PasswordEncoder} bean (consumed by {@code AuthService} and
 * {@code DataInitializer}). The filter chain is stateless, CSRF is disabled,
 * {@code /api/auth/login} is permitted without authentication, and every other route
 * requires an authenticated request. The {@link JwtAuthFilter} is registered ahead of the
 * username/password filter; unauthenticated requests receive a JSON 401 envelope and
 * access-denied responses a JSON 403 envelope.</p>
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;
    private final ObjectMapper objectMapper;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter, ObjectMapper objectMapper) {
        this.jwtAuthFilter = jwtAuthFilter;
        this.objectMapper = objectMapper;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session ->
                        session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/login").permitAll()
                        .anyRequest().authenticated())
                .exceptionHandling(ex -> ex
                        .authenticationEntryPoint((request, response, authException) ->
                                writeError(response, 401, "未认证"))
                        .accessDeniedHandler((request, response, exception) ->
                                writeError(response, 403, "权限不足")))
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    /**
     * Prevents Spring Boot from also registering {@link JwtAuthFilter} as a top-level
     * servlet filter; it runs only inside the security filter chain.
     */
    @Bean
    public FilterRegistrationBean<JwtAuthFilter> jwtAuthFilterRegistration(JwtAuthFilter filter) {
        FilterRegistrationBean<JwtAuthFilter> registration = new FilterRegistrationBean<>(filter);
        registration.setEnabled(false);
        return registration;
    }

    private void writeError(HttpServletResponse response, int status, String message) throws IOException {
        response.setStatus(status);
        response.setContentType("application/json");
        response.setCharacterEncoding("UTF-8");
        objectMapper.writeValue(response.getOutputStream(), ApiResponse.error(status, message));
    }
}

package com.cloudrecord.platform.controller;

import com.cloudrecord.platform.dto.ApiResponse;
import com.cloudrecord.platform.dto.LoginRequest;
import com.cloudrecord.platform.dto.LoginResponse;
import com.cloudrecord.platform.service.AuthService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Authentication routes. {@code POST /api/auth/login} is the only route reachable without
 * an {@code Authorization} header. The HTTP status equals the envelope {@code code}.
 */
@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<ApiResponse<LoginResponse>> login(@RequestBody LoginRequest request) {
        ApiResponse<LoginResponse> response = authService.login(request);
        return ResponseEntity.status(response.getCode()).body(response);
    }
}

